// Comms director: decides WHAT is said and WHEN from the real state of the flight, instead of playing canned audio on a timer.
//
// ATC traffic is still generated by atc.ts (driven by the departure / arrival state machines in game.ts). This module adds the
// rest of the flight-deck and cabin voice: the pilot-monitoring (PM) callouts of an Airbus A320 SOP (take-off: THRUST SET, 100,
// V1, ROTATE, POSITIVE RATE, GEAR UP; landing: spoilers, reverse, decel, 70 knots), stabilised-approach gates, configuration
// call-backs that read the real gear / flap / spoiler state, cabin PAs, and context-aware nudges when the player stalls.
// Every line is spoken AND captioned through the shared VoiceBus (speech.ts), with a hand-written Indonesian transcript.
//
// Sources for the callouts: Airbus A320 FCOM/FCTM normal procedures as taught in SOP summaries — PM calls "thrust set", "100",
// "V1" (V1 is called by the PM on most operators' SOPs), "rotate", "positive climb/rate"; PF commands "gear up"; on landing the
// PM calls "spoilers", "reverse green", "decel" and "70 knots" — and the FAA sterile-cockpit rule (14 CFR 121.542) that
// non-essential talk is held below 10,000 ft and during taxi, take-off and landing (we hold PA and small talk, never ATC).
import type { VoiceBus, CaptionKind, VoicePersona } from './speech';

export interface CommsSnap {
  kind: 'piston' | 'turboprop' | 'jet';
  startMode: 'runway' | 'cruise' | 'final';
  wow: boolean; gs: number; ias: number; vsFpm: number; aglFt: number; altFt: number; throttle: number;
  flapsIdx: number; flapDetents: number; gearDown: boolean; spoilersArmed: boolean; spoilersOut: boolean; reverse: boolean; autobrake: number;
  parking: boolean; enginesRunning: number; enginesStarting: number; engineCount: number; landingLight: boolean;
  phase: string; distNm: number; eteMin: number; depStage: number; pushbackActive: boolean;
  v1: number; vr: number; vapp: number; paWelcome: boolean; paLanding: boolean;
}
export interface CommsCtx { callsign: string; city: string; fromName: string; spot: string; night: boolean; rwy: string }
export interface CommsHost { snap: (out: CommsSnap) => void; ctx: () => CommsCtx }

type Speaker = 'fo' | 'purser' | 'pa';
const SPEAKERS: Record<Speaker, { who: string; label: string; kind: CaptionKind; persona: VoicePersona; rate: number; pitch: number }> = {
  fo: { who: 'FO', label: 'First Officer', kind: 'crew', persona: 'fo', rate: 1.04, pitch: 1.0 },
  purser: { who: 'PURSER', label: 'Purser', kind: 'crew', persona: 'pa', rate: 1.0, pitch: 1.05 },
  pa: { who: 'CABIN', label: 'Cabin PA', kind: 'pa', persona: 'pa', rate: 0.98, pitch: 1.0 },
};
interface CueOpts { priority?: 0 | 1 | 2 | 3; ttl?: number; speech?: string; hold?: boolean; repeat?: boolean }

const IDX_EN = ['up', 'one', 'two', 'three', 'full'];
const flapsEn = (i: number, n: number) => (i === 0 ? 'Flaps up' : i >= n ? 'Flaps full' : `Flaps ${i}`);
const flapsSay = (i: number, n: number) => (i === 0 ? 'Flaps up' : i >= n ? 'Flaps full' : `Flaps ${IDX_EN[i]}`);
const flapsId = (i: number, n: number) => (i === 0 ? 'Flap naik' : i >= n ? 'Flap penuh' : `Flap ${i}`);
const spellDigits = (n: number) => String(n).split('').map((d) => ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'][+d]).join(' ');
const hm = (min: number) => { const h = Math.floor(min / 60), m = Math.round(min % 60); return { h, m }; };

export class CommsDirector {
  private fired = new Set<string>();
  private s: CommsSnap = {
    kind: 'jet', startMode: 'runway', wow: true, gs: 0, ias: 0, vsFpm: 0, aglFt: 0, altFt: 0, throttle: 0, flapsIdx: 0, flapDetents: 4, gearDown: true, spoilersArmed: false,
    spoilersOut: false, reverse: false, autobrake: 0, parking: true, enginesRunning: 0, enginesStarting: 0, engineCount: 2, landingLight: false, phase: 'taxi', distNm: 0, eteMin: 0,
    depStage: 0, pushbackActive: false, v1: 140, vr: 145, vapp: 135, paWelcome: false, paLanding: false,
  };
  private t = 0; private id = 2_000_000; private primed = false;
  private airborne = false; private airborneT = 0; private rolling = false; private posRateT = -1;
  private prevWow = true; private prevGear = true; private prevAlt = -1; private prevAgl = -1;
  private flapsSeen = 0; private flapsPending = -1; private flapsT = 0;
  private touchT = -1; private landed = false; private levelT = -1; private stableChecked = false; private gateChecked = false;
  private allEnginesT = -1; private depStage5T = -1; private nudges = 0; private nudgeT = 0; private idleStartT = 0;
  constructor(private bus: VoiceBus, private host: CommsHost) {}

  /** New flight / restart: every cue becomes available again. */
  reset() {
    this.fired.clear(); this.primed = false; this.t = 0; this.airborne = false; this.airborneT = 0; this.rolling = false; this.posRateT = -1;
    this.prevWow = true; this.prevGear = true; this.prevAlt = -1; this.prevAgl = -1; this.flapsSeen = 0; this.flapsPending = -1; this.flapsT = 0;
    this.touchT = -1; this.landed = false; this.levelT = -1; this.stableChecked = false; this.gateChecked = false;
    this.allEnginesT = -1; this.depStage5T = -1; this.nudges = 0; this.nudgeT = 0; this.idleStartT = 0;
    this.bus.cancelWhere((u) => u.key.startsWith('crew:')); this.bus.sterile = false;
  }

  /** Called every frame while a flight is actually running (not paused / menu / loading). */
  update(dt: number) {
    const s = this.s; this.host.snap(s); this.t += dt;
    const jet = s.kind === 'jet';
    // ---- sterile phases: no PA / small talk during taxi-out roll, take-off, below 1,500 ft and the landing roll ----
    const sterile = (s.wow && s.throttle > 0.6 && s.gs > 20 && !this.landed) || (!s.wow && s.aglFt < 1500) || (this.landed && s.gs > 30);
    if (sterile !== this.bus.sterile) { this.bus.sterile = sterile; if (!sterile) this.bus.poke(); }
    if (!this.primed) { this.primed = true; this.prevAlt = s.altFt; this.prevAgl = s.aglFt; this.prevWow = s.wow; this.prevGear = s.gearDown; this.flapsSeen = s.flapsIdx; this.airborne = !s.wow && s.startMode !== 'runway'; }
    this.session(s);
    if (s.startMode === 'runway') this.ground(s, jet);
    if (jet) this.takeoffRoll(s);
    this.airborneLogic(s, jet, dt);
    if (jet) this.landing(s);
    this.prevWow = s.wow; this.prevGear = s.gearDown; this.prevAlt = s.altFt; this.prevAgl = s.aglFt;
  }

  // ------------------------------------------------------------------------------------------------------------------
  // session start
  // ------------------------------------------------------------------------------------------------------------------
  private session(s: CommsSnap) {
    if (this.t < 2.2 || s.kind !== 'jet') return;
    const c = this.host.ctx(), greet = c.night ? 'Good evening' : 'Good day', greetId = c.night ? 'Selamat malam' : 'Selamat siang';
    if (s.startMode === 'runway') {
      const spot = c.spot && c.spot !== 'the apron' ? c.spot : 'the apron';
      this.cue('start-fo', 'fo', `${greet}, Captain. We are parked at ${spot}, cold and dark. Battery on whenever you are ready.`,
        `${greetId}, Kapten. Kita parkir di ${spot === 'the apron' ? 'apron' : spot}, kokpit dalam kondisi mati. Nyalakan baterai kapan pun Anda siap.`, { priority: 1, ttl: 20 });
    } else if (s.startMode === 'cruise') {
      this.cue('start-fo', 'fo', `${greet}, Captain. We are level at flight level ${Math.round(s.altFt / 1000) * 10}, ${Math.round(s.distNm)} nautical miles to ${c.city}.`,
        `${greetId}, Kapten. Kita level di level penerbangan ${Math.round(s.altFt / 1000) * 10}, ${Math.round(s.distNm)} mil laut menuju ${c.city}.`, { priority: 1, ttl: 20, speech: `${greet}, Captain. We are level at flight level ${spellDigits(Math.round(s.altFt / 1000) * 10)}, ${Math.round(s.distNm)} nautical miles to ${c.city}.` });
    } else {
      this.cue('start-fo', 'fo', `Captain, we are on final for runway ${c.rwy}, ${Math.round(s.distNm)} miles to go. Check gear and flaps.`,
        `Kapten, kita di final landasan pacu ${c.rwy}, ${Math.round(s.distNm)} mil lagi. Periksa roda pendaratan dan flap.`, { priority: 1, ttl: 20 });
    }
  }

  // ------------------------------------------------------------------------------------------------------------------
  // cold & dark -> line-up
  // ------------------------------------------------------------------------------------------------------------------
  private ground(s: CommsSnap, jet: boolean) {
    if (this.airborne || !s.wow) return;
    const c = this.host.ctx();
    if (jet) {
      // Purser report once the cabin would be ready (about 12 s in) — only while still parked and unpowered.
      if (this.t > 12 && s.enginesRunning === 0 && s.gs < 1) this.cue('purser', 'purser', 'Captain, the purser. Boarding is complete and the cabin is secure.', 'Kapten, ini purser. Boarding selesai dan kabin sudah aman.', { priority: 1, ttl: 40, hold: true });
      // First engine start or pushback: doors to automatic (A320 SOP cabin PA).
      if ((s.enginesStarting > 0 || s.enginesRunning > 0 || s.pushbackActive)) this.cue('doors', 'pa', 'Cabin crew, doors to automatic and cross-check.', 'Awak kabin, pintu ke mode otomatis dan periksa silang.', { priority: 1, ttl: 40, hold: true });
      // All engines running and stable: report the real configuration.
      if (s.enginesRunning >= s.engineCount && s.engineCount > 0) { if (this.allEnginesT < 0) this.allEnginesT = this.t; } else this.allEnginesT = -1;
      if (this.allEnginesT >= 0 && this.t - this.allEnginesT > 4 && s.depStage < 4) {
        const f = s.flapsIdx;
        this.cue('after-start', 'fo', f === 0 ? 'Both engines stable. Flaps are still up. Set take-off flaps when you are ready.' : `Both engines stable. ${flapsEn(f, s.flapDetents)} set.`,
          f === 0 ? 'Kedua mesin stabil. Flap masih naik. Atur flap lepas landas bila Anda siap.' : `Kedua mesin stabil. ${flapsId(f, s.flapDetents)} terpasang.`, { priority: 1, ttl: 30 });
      }
      // Line-up checks that read the real switch positions, then the cabin call.
      if (s.depStage >= 4) {
        const bad: string[] = [], badId: string[] = [];
        if (s.flapsIdx === 0) { bad.push('flaps not set'); badId.push('flap belum diatur'); }
        if (!s.spoilersArmed) { bad.push('ground spoilers not armed'); badId.push('ground spoiler belum diarmed'); }
        const en = bad.length ? `Before take-off: ${bad.join(', ')}.` : `Before take-off: ${flapsEn(s.flapsIdx, s.flapDetents)}, ground spoilers armed.`;
        const idn = badId.length ? `Sebelum lepas landas: ${badId.join(', ')}.` : `Sebelum lepas landas: ${flapsId(s.flapsIdx, s.flapDetents)}, ground spoiler diarmed.`;
        if (this.cue('before-to', 'fo', en, idn, { priority: 1, ttl: 40 })) {
          this.cue('seats', 'pa', 'Cabin crew, seats for take-off.', 'Awak kabin, duduk untuk lepas landas.', { priority: 1, ttl: 40 });
        }
      }
      // The tower is waiting and nothing is happening.
      if (s.depStage >= 5) { if (this.depStage5T < 0) this.depStage5T = this.t; } else this.depStage5T = -1;
      if (this.depStage5T >= 0 && s.gs < 3 && s.throttle < 0.3 && this.t - this.depStage5T > 50) this.cue('tower-waiting', 'fo', 'Captain, we have take-off clearance. Tower is waiting for us.', 'Kapten, kita sudah mendapat izin lepas landas. Tower menunggu kita.', { priority: 1, ttl: 20, hold: true });
    }
    // Idle nudge: cold and dark for a long time.
    const cold = s.enginesRunning === 0 && s.enginesStarting === 0 && !s.pushbackActive && s.gs < 1 && s.depStage <= 1;
    if (!cold) { this.idleStartT = this.t; return; }
    const idle = this.t - this.idleStartT;
    if (this.nudges === 0 && idle > 55) {
      this.nudges = 1; this.nudgeT = this.t;
      this.cue('nudge1', jet ? 'fo' : 'purser', 'Captain, whenever you are ready: battery, beacon, then engine start.', 'Kapten, kapan pun Anda siap: baterai, beacon, lalu start mesin.', { priority: 1, ttl: 20, hold: true });
    } else if (this.nudges === 1 && this.t - this.nudgeT > 95) {
      this.nudges = 2;
      this.cue('nudge2', jet ? 'fo' : 'purser', `Captain, we are still cold and dark at ${c.fromName}. Tell me when you want to start.`, `Kapten, kita masih dalam kondisi mati di ${c.fromName}. Beri tahu saya kapan Anda ingin mulai.`, { priority: 1, ttl: 20, hold: true });
    }
  }

  // ------------------------------------------------------------------------------------------------------------------
  // take-off roll: THRUST SET -> 100 -> V1 -> ROTATE
  // ------------------------------------------------------------------------------------------------------------------
  private takeoffRoll(s: CommsSnap) {
    if (this.airborne || s.startMode !== 'runway') return;
    const roll = s.wow && s.throttle >= 0.75 && s.gs > 4;
    if (roll) {
      this.rolling = true;
      if (s.gs > 30) this.cue('to-thrust', 'fo', 'Thrust set.', 'Daya terpasang.', { priority: 2, ttl: 3 });
      if (s.ias >= 100) this.cue('to-100', 'fo', '100 knots.', '100 knot.', { priority: 2, ttl: 3, speech: 'One hundred knots.' });
      if (s.ias >= s.v1) this.cue('to-v1', 'fo', 'V1.', 'V1.', { priority: 2, ttl: 3, speech: 'V one.' });
      if (s.ias >= s.vr) this.cue('to-rotate', 'fo', 'Rotate.', 'Rotasi.', { priority: 2, ttl: 3 });
    } else if (this.rolling && s.wow && s.throttle < 0.3 && s.gs < 25) {
      // aborted / thrust pulled back: the sequence is available again for the next attempt
      this.rolling = false; for (const k of ['to-thrust', 'to-100', 'to-v1', 'to-rotate']) this.fired.delete(`crew:${k}`);
    }
  }

  // ------------------------------------------------------------------------------------------------------------------
  // climb / cruise / descent / approach configuration
  // ------------------------------------------------------------------------------------------------------------------
  private airborneLogic(s: CommsSnap, jet: boolean, dt: number) {
    const c = this.host.ctx();
    if (!s.wow && !this.airborne && (s.aglFt > 5 || s.startMode !== 'runway')) { this.airborne = true; this.airborneT = 0; this.landed = false; this.touchT = -1; this.rolling = false; }
    if (!this.airborne) return;
    if (!s.wow) this.airborneT += dt;
    if (!jet) return;
    // positive rate, gear up
    if (s.startMode === 'runway' && !s.wow && this.posRateT < 0 && s.vsFpm > 200 && s.aglFt > 12 && this.airborneT < 40) {
      if (this.cue('posrate', 'fo', 'Positive rate.', 'Laju naik positif.', { priority: 2, ttl: 3 })) this.posRateT = this.t;
    }
    if (this.posRateT >= 0 && this.prevGear && !s.gearDown && !s.wow) this.cue('gear-up', 'fo', 'Gear up.', 'Roda pendaratan naik.', { priority: 2, ttl: 3, repeat: true });
    if (this.posRateT >= 0 && s.gearDown && this.t - this.posRateT > 9 && s.aglFt > 250 && s.aglFt < 6000 && !s.wow) this.cue('gear-still-down', 'fo', 'Captain, the gear is still down.', 'Kapten, roda pendaratan masih turun.', { priority: 2, ttl: 5 });
    // gear down in flight (approach)
    if (!this.prevGear && s.gearDown && !s.wow && s.aglFt > 50) this.cue('gear-down', 'fo', 'Gear down.', 'Roda pendaratan turun.', { priority: 2, ttl: 3, repeat: true });
    // flap handle: announced once it settles, airborne only
    if (!s.wow && s.flapsIdx !== this.flapsSeen) {
      if (s.flapsIdx !== this.flapsPending) { this.flapsPending = s.flapsIdx; this.flapsT = this.t; }
      if (this.t - this.flapsT > 0.9) {
        const i = s.flapsIdx, n = s.flapDetents; this.flapsSeen = i;
        this.cue('flaps', 'fo', `${flapsEn(i, n)}.`, `${flapsId(i, n)}.`, { priority: 2, ttl: 3.5, speech: `${flapsSay(i, n)}.`, repeat: true });
      }
    } else if (s.wow) this.flapsSeen = s.flapsIdx;
    // altitude gates (crossings, never absolute: a spawn above the level must not fire)
    if (this.prevAlt >= 0) {
      if (this.prevAlt < 10000 && s.altFt >= 10000 && s.vsFpm > 0) { this.cue('climb-10k', 'fo', s.landingLight ? 'Ten thousand feet. Landing lights are still on.' : 'Ten thousand feet.', s.landingLight ? 'Sepuluh ribu kaki. Lampu pendaratan masih menyala.' : 'Sepuluh ribu kaki.', { priority: 2, ttl: 4, repeat: true }); }
      if (this.prevAlt >= 10000 && s.altFt < 10000 && s.vsFpm < 0) { this.cue('desc-10k', 'fo', s.landingLight ? 'Ten thousand feet, landing lights on.' : 'Ten thousand feet. Landing lights are off.', s.landingLight ? 'Sepuluh ribu kaki, lampu pendaratan menyala.' : 'Sepuluh ribu kaki. Lampu pendaratan mati.', { priority: 2, ttl: 4, repeat: true }); }
    }
    // level at cruise + captain's PA
    if (s.phase === 'cruise' && s.startMode === 'runway' && this.levelT < 0 && s.vsFpm < 300 && s.altFt > 5000) {
      this.levelT = this.t; const fl = Math.round(s.altFt / 1000) * 10;
      this.cue('level', 'fo', `Level, flight level ${fl}.`, `Level di level penerbangan ${fl}.`, { priority: 1, ttl: 12, speech: `Level, flight level ${spellDigits(fl)}.`, hold: true });
    }
    if (this.levelT >= 0 && this.t - this.levelT > 28) {
      const fl = Math.round(s.altFt / 1000) * 10, { h, m } = hm(s.eteMin);
      const timeEn = h > 0 ? `${h} hour${h > 1 ? 's' : ''} and ${m} minutes` : `${m} minutes`, timeId = h > 0 ? `${h} jam ${m} menit` : `${m} menit`;
      this.cue('cruise-pa', 'pa', `Ladies and gentlemen, this is your captain speaking. We have reached our cruising altitude of flight level ${fl}. We have ${Math.round(s.distNm)} nautical miles to go to ${c.city}, about ${timeEn}. Please keep your seat belt fastened while seated.`,
        `Para penumpang yang terhormat, ini kapten Anda. Kita telah mencapai ketinggian jelajah level penerbangan ${fl}. Masih ada ${Math.round(s.distNm)} mil laut menuju ${c.city}, sekitar ${timeId}. Mohon tetap kenakan sabuk pengaman saat duduk.`,
        { priority: 1, ttl: 90, hold: true, speech: `Ladies and gentlemen, this is your captain speaking. We have reached our cruising altitude of flight level ${spellDigits(fl)}. We have ${Math.round(s.distNm)} nautical miles to go to ${c.city}, about ${timeEn}. Please keep your seat belt fastened while seated.` });
    }
    // top of descent
    if (s.phase === 'descent' && this.airborne) {
      const { h, m } = hm(Math.max(5, s.eteMin));
      this.cue('tod', 'fo', 'Top of descent. Starting descent.', 'Titik mulai turun. Memulai penurunan.', { priority: 1, ttl: 15 });
      this.cue('descent-pa', 'pa', `Ladies and gentlemen, we have started our descent into ${c.city}. We expect to be on the ground in about ${h > 0 ? `${h} hour and ` : ''}${m} minutes.`,
        `Para penumpang yang terhormat, kita mulai turun menuju ${c.city}. Kita perkirakan mendarat sekitar ${h > 0 ? `${h} jam ` : ''}${m} menit lagi.`, { priority: 1, ttl: 90, hold: true });
    }
    if (!s.paLanding && this.airborne && s.altFt < 7000 && s.vsFpm < -200 && s.distNm < 35 && !s.wow && s.aglFt > 1800)
      this.cue('landing-pa', 'pa', 'Cabin crew, prepare for landing.', 'Awak kabin, bersiap untuk mendarat.', { priority: 1, ttl: 40, hold: true });
    // stabilised-approach gates (1,000 ft: configuration & speed; 500 ft: go-around advice)
    if (s.aglFt > 1800) { this.gateChecked = false; this.stableChecked = false; }
    const approaching = !s.wow && s.vsFpm < -250 && s.distNm < 14 && s.gs > 60;
    if (approaching && this.prevAgl > 1000 && s.aglFt <= 1000 && !this.gateChecked) {
      this.gateChecked = true;
      const issue = !s.gearDown ? ['Gear is not down.', 'Roda pendaratan belum turun.'] : s.flapsIdx < Math.max(1, s.flapDetents - 1) ? ['Flaps not in landing configuration.', 'Flap belum dalam konfigurasi mendarat.']
        : s.ias > s.vapp + 20 ? [`Speed ${Math.round(s.ias)}, too fast.`, `Kecepatan ${Math.round(s.ias)}, terlalu cepat.`] : s.ias < s.vapp - 5 ? [`Speed ${Math.round(s.ias)}, too slow.`, `Kecepatan ${Math.round(s.ias)}, terlalu lambat.`] : null;
      this.cue('gate-1000', 'fo', issue ? `One thousand feet. ${issue[0]} Not stable.` : 'One thousand feet. Stable.', issue ? `Seribu kaki. ${issue[1]} Tidak stabil.` : 'Seribu kaki. Stabil.', { priority: 2, ttl: 5, repeat: true });
      this.stableChecked = !issue;
    }
    if (approaching && this.prevAgl > 500 && s.aglFt <= 500 && this.gateChecked && !this.stableChecked) {
      const ok = s.gearDown && s.flapsIdx >= Math.max(1, s.flapDetents - 1) && s.ias <= s.vapp + 20;
      if (!ok) { this.cue('gate-500', 'fo', 'Five hundred. Not stable. Recommend go-around.', 'Lima ratus. Tidak stabil. Disarankan go-around.', { priority: 2, ttl: 5, repeat: true }); }
    }
  }

  // ------------------------------------------------------------------------------------------------------------------
  // landing roll
  // ------------------------------------------------------------------------------------------------------------------
  private landing(s: CommsSnap) {
    if (this.airborne && !this.prevWow && s.wow && this.touchT < 0 && this.airborneT > 20) {
      this.touchT = this.t; this.landed = true;
      for (const k of ['ld-spoilers', 'ld-reverse', 'ld-decel', 'ld-70']) this.fired.delete(`crew:${k}`);
    }
    if (this.touchT < 0) return;
    const dt = this.t - this.touchT;
    if (dt > 0.7) this.cue('ld-spoilers', 'fo', s.spoilersOut ? 'Spoilers.' : 'No spoilers.', s.spoilersOut ? 'Spoiler keluar.' : 'Spoiler tidak keluar.', { priority: 2, ttl: 3 });
    if (dt > 1.8 && s.gs > 60) this.cue('ld-reverse', 'fo', s.reverse ? 'Reverse green.' : 'No reverse.', s.reverse ? 'Reverse hijau.' : 'Tanpa reverse.', { priority: 2, ttl: 3 });
    if (dt > 3 && s.autobrake > 0 && s.gs > 60) this.cue('ld-decel', 'fo', 'Decel.', 'Deselerasi.', { priority: 2, ttl: 3 });
    if (dt > 3 && s.gs <= 72) this.cue('ld-70', 'fo', '70 knots.', '70 knot.', { priority: 2, ttl: 3, speech: 'Seventy knots.' });
    // rolled out (or taxiing in): the next departure starts from a clean slate
    if (dt > 90 || (dt > 6 && s.gs < 2)) { this.touchT = -1; this.landed = false; this.airborne = false; this.airborneT = 0; }
  }

  // ------------------------------------------------------------------------------------------------------------------
  private cue(id: string, sp: Speaker, en: string, idn: string, o: CueOpts = {}): boolean {
    const key = `crew:${id}`;
    if (this.fired.has(key) && !o.repeat) return false;
    const S = SPEAKERS[sp];
    const ok = this.bus.say({
      key, speech: o.speech ?? en, persona: S.persona, priority: o.priority ?? 1, ttl: o.ttl, rate: S.rate, pitch: S.pitch, volume: 1,
      replay: (o.priority ?? 1) <= 1, holdWhenSterile: o.hold ?? (sp === 'pa'),
      caption: { id: ++this.id, kind: S.kind, who: S.who, label: S.label, text: en, textId: idn },
    });
    if (ok) this.fired.add(key);
    return ok;
  }
}
